script.setup:
// PixiJS renders into the scene's own WebGL2 context: up to 30k additive particles
// in one batched ParticleContainer, drawn into a render texture that keeps trails,
// then composited twice (sharp + BlurFilter glow) under a DisplacementFilter.
const PIXI = await ctx.utils.import("https://cdn.jsdelivr.net/npm/pixi.js@8.21.0/dist/pixi.min.mjs");
const [w0, h0] = ctx.resolution;
// autoDetectRenderer also loads the browser extensions (filters, events).
const renderer = await PIXI.autoDetectRenderer({
  preference: "webgl", canvas: ctx.canvas, context: ctx.gl, width: w0, height: h0, resolution: 1, autoDensity: false,
  background: "#04050b", antialias: true, eventFeatures: { move: false, globalMove: false, click: false, wheel: false },
});

// A soft round dot drawn once on a 2D canvas: every particle shares it, so they batch.
const dotCanvas = Object.assign(document.createElement("canvas"), { width: 64, height: 64 });
const g2 = dotCanvas.getContext("2d");
const grad = g2.createRadialGradient(32, 32, 0, 32, 32, 32);
grad.addColorStop(0, "rgba(255,255,255,1)");
grad.addColorStop(0.18, "rgba(255,255,255,0.85)");
grad.addColorStop(0.45, "rgba(255,255,255,0.22)");
grad.addColorStop(1, "rgba(255,255,255,0)");
g2.fillStyle = grad; g2.fillRect(0, 0, 64, 64);
const dot = new PIXI.Texture({ source: new PIXI.CanvasSource({ resource: dotCanvas }) });

// Tileable noise for the DisplacementFilter (sums of sines with whole periods).
const NS = 256, noiseCanvas = Object.assign(document.createElement("canvas"), { width: NS, height: NS });
const nctx = noiseCanvas.getContext("2d"), img = nctx.createImageData(NS, NS);
for (let y = 0; y < NS; y++) for (let x = 0; x < NS; x++) {
  const u = (x / NS) * Math.PI * 2, v = (y / NS) * Math.PI * 2;
  const r = 0.5 + 0.25 * Math.sin(u * 2 + Math.sin(v * 3) * 1.5) + 0.15 * Math.sin(v * 5 - u * 3);
  const gg = 0.5 + 0.25 * Math.cos(v * 2 + Math.sin(u * 3) * 1.5) + 0.15 * Math.cos(u * 4 + v * 3);
  const i = (y * NS + x) * 4;
  img.data[i] = r * 255; img.data[i + 1] = gg * 255; img.data[i + 2] = 128; img.data[i + 3] = 255;
}
nctx.putImageData(img, 0, 0);
const noiseTex = new PIXI.Texture({ source: new PIXI.CanvasSource({ resource: noiseCanvas, addressMode: "repeat" }) });

// Paint layer: a translucent black rect fades last frame (trails), then the particles add on top.
const paint = new PIXI.Container();
const fade = new PIXI.Graphics().rect(0, 0, 1, 1).fill(0x000000);
const particles = new PIXI.ParticleContainer({
  texture: dot, blendMode: "add",
  dynamicProperties: { position: true, color: true, vertex: true, rotation: false, uvs: false },
});
paint.addChild(fade, particles);

const MAX = 30000, pool = [], data = new Float32Array(MAX * 4); // x, y, age, life
for (let i = 0; i < MAX; i++) {
  pool.push(new PIXI.Particle({ texture: dot, anchorX: 0.5, anchorY: 0.5 }));
  data[i * 4 + 2] = Math.random() * 6; data[i * 4 + 3] = 3 + Math.random() * 5;
  data[i * 4] = Math.random(); data[i * 4 + 1] = Math.random();
}

// Composite: background vignette, blurred glow copy, sharp copy — both of the same render texture.
const stage = new PIXI.Container();
const bg = new PIXI.Graphics();
const rt = PIXI.RenderTexture.create({ width: w0, height: h0 });
const glow = new PIXI.Sprite(rt), sharp = new PIXI.Sprite(rt);
glow.blendMode = "add"; sharp.blendMode = "add";
const blur = new PIXI.BlurFilter({ strength: 12, quality: 4 });
glow.filters = [blur];
const comp = new PIXI.Container();
// The filter samples the map through this sprite's transform, so moving it scrolls the warp.
const dispSprite = new PIXI.Sprite(noiseTex);
dispSprite.renderable = false;
dispSprite.scale.set(5);
const warp = new PIXI.DisplacementFilter({ sprite: dispSprite, scale: 30 });
comp.addChild(glow, sharp);
comp.filters = [warp];
stage.addChild(bg, dispSprite, comp);

Object.assign(ctx.state, {
  PIXI, renderer, stage, paint, fade, particles, pool, data, MAX, rt, glow, sharp, blur, warp, comp, bg, dispSprite,
  dot, noiseTex, count: 0, size: [0, 0], mx: 0.5, my: 0.5, t: 0,
});

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution, PIXI = s.PIXI;
if (s.size[0] !== w || s.size[1] !== h) {
  s.size = [w, h];
  s.renderer.resize(w, h, 1);
  s.rt.resize(w, h);
  s.comp.filterArea = new PIXI.Rectangle(0, 0, w, h);
  s.fade.clear().rect(0, 0, w, h).fill(0x000000);
  // Deep blue vignette behind everything.
  s.bg.clear();
  for (let i = 12; i > 0; i--) {
    const k = i / 12;
    s.bg.circle(w / 2, h / 2, Math.hypot(w, h) * 0.55 * k).fill({ color: 0x0b1030, alpha: 0.09 * (1 - k * 0.7) });
  }
}
// Particle count follows the control: the batch just gets a longer list.
const n = Math.max(500, Math.min(s.MAX, Math.round(u.u_count)));
if (n !== s.count) {
  s.particles.particleChildren = s.pool.slice(0, n);
  s.particles.update();
  s.count = n;
}
const dt = Math.min(ctx.dt, 0.05) * u.u_speed;
s.t += dt;
const t = s.t, aspect = w / h, d = s.data, ps = s.pool;
// Mouse stirs a vortex; it eases toward the pointer.
s.mx += (ctx.mouse[0] - s.mx) * 0.08; s.my += (ctx.mouse[1] - s.my) * 0.08;
const vx0 = s.mx * aspect, vy0 = s.my, swirl = ctx.mouseDown ? 3 : 1;
const [ar, ag, ab] = u.u_color_a, [br, bg_, bb] = u.u_color_b;
const scale = (Math.min(w, h) / 900) * u.u_size;
const deposit = Math.min(4, Math.max(1, ctx.dt * 60));
for (let i = 0; i < n; i++) {
  const o = i * 4;
  let x = d[o], y = d[o + 1], age = d[o + 2] + dt;
  const life = d[o + 3];
  // Divergence-free flow: velocity is the curl of a drifting stream function.
  const X = x * aspect, Y = y;
  const a1 = X * 2.1 + t * 0.21, b1 = Y * 2.7 - t * 0.17, a2 = X * 4.3 - Y * 3.1 + t * 0.37, a3 = Y * 5.2 + X * 1.3 - t * 0.29;
  let fx = -2.7 * Math.sin(a1) * Math.sin(b1) - 0.4 * 3.1 * Math.cos(a2) + 0.25 * 5.2 * Math.cos(a3);
  let fy = -2.1 * Math.cos(a1) * Math.cos(b1) - 0.4 * 4.3 * Math.cos(a2) - 0.25 * 1.3 * Math.cos(a3);
  // Vortex around the (eased) pointer.
  const dx = X - vx0, dy = Y - vy0, r2 = dx * dx + dy * dy + 0.004, fall = Math.exp(-r2 * 9) * swirl;
  fx += -dy * fall * 9 - dx * fall * 1.5; fy += dx * fall * 9 - dy * fall * 1.5;
  x += fx * dt * 0.07 / aspect; y += fy * dt * 0.07;
  if (age > life || x < -0.05 || x > 1.05 || y < -0.05 || y > 1.05) {
    x = Math.random(); y = Math.random(); age = 0;
  }
  d[o] = x; d[o + 1] = y; d[o + 2] = age;
  const sp = Math.min(1, Math.hypot(fx, fy) * 0.3);
  const k = sp * sp;
  const p = ps[i];
  p.x = x * w; p.y = y * h;
  const sz = scale * (0.035 + 0.05 * (1 - k)) * (0.6 + (i % 7) * 0.12);
  p.scaleX = p.scaleY = sz;
  p.tint = ((ar + (br - ar) * k) * 255) << 16 | ((ag + (bg_ - ag) * k) * 255) << 8 | ((ab + (bb - ab) * k) * 255);
  // Fade in and out over each particle's life.
  // Light left per frame scales with the frame's length, so slow machines (or 5 fps renders) build the same trails.
  p.alpha = Math.min(1, Math.min(1, age * 2, (life - age) * 1.5) * (0.16 + 0.4 * k) * deposit);
}
// Frame-rate independent trail fade.
s.fade.alpha = 1 - Math.pow(u.u_trail, Math.min(ctx.dt, 0.1) * 60);
s.blur.strength = 4 + u.u_glow * 22;
s.glow.alpha = Math.min(1.5, u.u_glow * 2);
s.warp.scale.set(u.u_warp, u.u_warp);
s.dispSprite.position.set(-((t * 40) % 1280), -((t * 25) % 1280));
// The runtime touched GL state since the last frame; Pixi caches it, so resync first.
s.renderer.resetState();
s.renderer.render({ container: s.paint, target: s.rt, clear: ctx.frame === 0 });
s.renderer.render({ container: s.stage });

script.cleanup:
const s = ctx.state;
s.rt?.destroy(true); s.dot?.destroy(true); s.noiseTex?.destroy(true);
s.stage?.destroy({ children: true }); s.paint?.destroy({ children: true });
s.renderer?.destroy();
